const legacySuppliers=deriveLegacySuppliers(legacy);stat(report,'suppliers').legacy=legacySuppliers.length;legacySuppliers.forEach(ls=>{const candidates=uniqueCandidates(merged.suppliers,[equalKey(x=>x.id,ls.id),equalKey(x=>x.name,ls.name)]);if(candidates.length>1){addConflict(report,'suppliers',ls,'Multiple supplier matches',candidates);return;}if(candidates.length===1){const t=candidates[0],changed=enrich(t,ls,new Set(['id','name']));maps.suppliers[ls.id]=t.id||t.name;stat(report,'suppliers').matched++;if(changed)stat(report,'suppliers').enriched++;return;}const n=clone(ls);if(!n.id||merged.suppliers.some(x=>String(x.id)===String(n.id)))n.id=nextId('SUP-MIG-',merged.suppliers);merged.suppliers.push(n);maps.suppliers[ls.id]=n.id;stat(report,'suppliers').created++;});

stat(report,'customers').legacy=arr(legacy.customers).length;arr(legacy.customers).forEach(lc=>{const keys=[equalKey(x=>x.id,lc.id),equalKey(x=>x.code,lc.code),equalKey(x=>x.email,lc.email)];const np=norm(postcodeOf(lc)),nn=norm(lc.name||lc.companyName);if(nn&&np)keys.push({test:x=>norm(x.name||x.companyName)===nn&&norm(postcodeOf(x))===np});const candidates=uniqueCandidates(merged.customers,keys);if(candidates.length>1){addConflict(report,'customers',lc,'Multiple customer matches',candidates);return;}if(candidates.length===1){const t=candidates[0],changed=enrich(t,lc,new Set(['id','code','name','companyName']));maps.customers[lc.id]=t.id;stat(report,'customers').matched++;if(changed)stat(report,'customers').enriched++;return;}const n=clone(lc);if(!n.id||merged.customers.some(x=>String(x.id)===String(n.id)))n.id=nextId('CUST-MIG-',merged.customers);n.code=n.code||n.id;merged.customers.push(n);maps.customers[lc.id]=n.id;stat(report,'customers').created++;});

stat(report,'products').legacy=arr(legacy.products).length;arr(legacy.products).forEach(lp=>{const candidates=uniqueCandidates(merged.products,[equalKey(x=>x.id,lp.id),equalKey(x=>x.sku,lp.sku),equalKey(x=>x.supplierSku,lp.supplierSku||lp.supplier_sku),equalKey(x=>x.barcode,lp.barcode),equalKey(x=>x.mpn,lp.mpn)]);if(candidates.length>1){addConflict(report,'products',lp,'Multiple product identity matches',candidates);return;}if(candidates.length===1){const t=candidates[0],changed=enrich(t,lp,new Set(['id','sku','name','cost','rrp','trade','wholesale','special']));const aliases=unionStrings(t.aliases,[]);[lp.id,lp.sku,lp.code].forEach(v=>{if(v&&norm(v)!==norm(t.id)&&norm(v)!==norm(t.sku)&&!aliases.some(a=>norm(a)===norm(v)))aliases.push(String(v));});if(aliases.length!==arr(t.aliases).length){t.aliases=aliases;}maps.products[lp.id]=t.id;stat(report,'products').matched++;if(changed)stat(report,'products').enriched++;return;}const n=clone(lp);if(!n.id||merged.products.some(x=>String(x.id)===String(n.id)))n.id=nextId('PROD-MIG-',merged.products);n.sku=n.sku||n.code||n.id;n.aliases=unionStrings(n.aliases,[lp.id]);merged.products.push(n);maps.products[lp.id]=n.id;stat(report,'products').created++;});

