function mergeRecordArray(entity,legacyList,currentList,opts){const s=stat(report,entity);s.legacy=arr(legacyList).length;arr(legacyList).forEach(lr=>{const id=lr&&lr.id;let existing=id?currentList.find(x=>String(x&&x.id)===String(id)):null;const prepared=opts&&opts.prepare?opts.prepare(lr):clone(lr);if(prepared==null){s.skipped++;return;}if(existing){let changed=enrich(existing,prepared,new Set((opts&&opts.skip)||['id']));if(opts&&opts.lines&&Array.isArray(prepared.lines)){if(!Array.isArray(existing.lines))existing.lines=[];const seen=new Set(existing.lines.map(lineIdentity));prepared.lines.forEach(line=>{const key=lineIdentity(line);if(!seen.has(key)){existing.lines.push(clone(line));seen.add(key);changed++;}else{const ex=existing.lines.find(x=>lineIdentity(x)===key);if(ex)changed+=enrich(ex,line,new Set(['id','productId','qty','price','unitCost']));}});}s.matched++;if(changed)s.enriched++;if(opts&&opts.map&&id)opts.map[id]=existing.id;return;}const n=prepared;if(!n.id||currentList.some(x=>String(x&&x.id)===String(n.id)))n.id=nextId((opts&&opts.prefix)||'MIG-',currentList);currentList.push(n);s.created++;if(opts&&opts.map&&id)opts.map[id]=n.id;});}

mergeRecordArray('jobs',legacy.jobs,merged.jobs,{prefix:'JOB-MIG-',map:maps.jobs,prepare:r=>{const n=clone(r);if(n.customerId)n.customerId=remapId(maps.customers,n.customerId);arr(n.materialPlan).forEach(x=>{if(x.productId)x.productId=remapId(maps.products,x.productId);});return n;}});
mergeRecordArray('salesOrders',legacy.salesOrders,merged.salesOrders,{prefix:'SO-MIG-',map:maps.salesOrders,lines:true,prepare:r=>{const n=clone(r);if(n.customerId)n.customerId=remapId(maps.customers,n.customerId);n.lines=arr(n.lines).map(line=>remapLine(line,maps)).filter(line=>!line.productId||merged.products.some(p=>String(p.id)===String(line.productId)));return n;}});
mergeRecordArray('purchaseOrders',legacy.purchaseOrders,merged.purchaseOrders,{prefix:'PO-MIG-',map:maps.purchaseOrders,lines:true,prepare:r=>{const n=clone(r);n.lines=arr(n.lines).map(line=>remapLine(line,maps)).filter(line=>!line.productId||merged.products.some(p=>String(p.id)===String(line.productId)));return n;}});

const stockStat=stat(report,'stock');stockStat.legacy=arr(legacy.stock).length;const stockKeys=new Set(merged.stock.map(r=>String(r.productId)+'|'+String(r.locationId)));arr(legacy.stock).forEach(row=>{const productId=remapId(maps.products,row.productId||row.product_id||row.variantId||row.variant_id),locationId=remapId(maps.locations,row.locationId||row.location_id||row.location||row.bin);if(!productId||!locationId||!merged.products.some(p=>String(p.id)===String(productId))||!merged.locations.some(l=>String(l.id)===String(locationId))){stockStat.skipped++;return;}const key=String(productId)+'|'+String(locationId);if(stockKeys.has(key)){stockStat.matched++;stockStat.skipped++;return;}merged.stock.push({productId,locationId,qty:Number(row.qty!=null?row.qty:row.quantity!=null?row.quantity:row.qty_on_hand||0)||0,allocated:Number(row.allocated!=null?row.allocated:row.qty_allocated||0)||0});stockKeys.add(key);stockStat.created++;});

