mergeRecordArray('goodsNotes',legacy.goodsNotes,merged.goodsNotes,{prefix:'GN-MIG-',lines:true,prepare:prepLinked});
mergeRecordArray('engineerRequests',legacy.engineerRequests,merged.engineerRequests,{prefix:'REQ-MIG-',lines:true,prepare:prepLinked});
mergeRecordArray('salesCredits',legacy.salesCredits,merged.salesCredits,{prefix:'SC-MIG-',lines:true,prepare:prepLinked});
