function backupCurrent(current,source){const backup={version:VERSION,createdAt:new Date().toISOString(),source:source||'legacy migration',data:clone(current)};const key='poolshed:v122:migrationBackup:'+backup.createdAt.replace(/[:.]/g,'-');try{if(global.localStorage)global.localStorage.setItem(key,JSON.stringify(backup));backup.storageKey=key;}catch(_){backup.storageKey='';backup.storageWarning='Local backup storage failed; retain the downloaded backup.';}return backup;}
function apply(legacy,options){const current=getData();if(!current||typeof current!=='object')return {ok:false,reason:'Canonical Pool Shed workspace is unavailable.'};const preview=plan(legacy,current,options||{});const backup=backupCurrent(current,options&&options.source);Object.keys(current).forEach(k=>delete current[k]);Object.assign(current,clone(preview.merged));if(!Array.isArray(current.legacyMigrationHistory))current.legacyMigrationHistory=[];current.legacyMigrationHistory.push({version:VERSION,appliedAt:new Date().toISOString(),source:options&&options.source||'legacy',backupKey:backup.storageKey||'',report:clone(preview.report)});try{if(typeof global.saveAppData==='function')global.saveAppData();}catch(_){return {ok:false,reason:'Migration merged but normal Pool Shed save failed.',report:preview.report,backup};}return {ok:true,report:preview.report,backup,mappings:preview.mappings};}
function detectLocalStorage(storage){const store=storage||global.localStorage;if(!store)return [];const out=[],seen=new Set();function add(key,value){if(!value||seen.has(key))return;try{const data=typeof value==='string'?JSON.parse(value):value;if(!data||typeof data!=='object')return;seen.add(key);out.push({id:'local:'+key,label:key,source:'localStorage',updatedAt:'',data});}catch(_){}}try{add('poolbros:system:appData',store.getItem('poolbros:system:appData'));for(let i=0;i<Number(store.length||0);i++){const key=store.key(i);if(key&&/^poolbros:.*:appData$/.test(key)&&key!=='poolbros:system:appData')add(key,store.getItem(key));}}catch(_){}return out;}
async function readIndexedDb(indexedDb){const idb=indexedDb||global.indexedDB;if(!idb)return [];return await new Promise(resolve=>{let request;let settled=false;function finish(v){if(settled)return;settled=true;resolve(v);}try{request=idb.open('the-pool-shed-offline',1);}catch(_){return finish([]);}request.onerror=()=>finish([]);request.onupgradeneeded=()=>{try{request.transaction.abort();}catch(_){}finish([]);};request.onsuccess=()=>{const db=request.result;if(settled){try{db.close();}catch(_){}return;}if(!db.objectStoreNames.contains('state')){db.close();return finish([]);}try{const tx=db.transaction('state','readonly'),r=tx.objectStore('state').get('appData');r.onerror=()=>{db.close();finish([]);};r.onsuccess=()=>{const row=r.result;db.close();finish(row&&row.payload?[{id:'indexeddb:appData',label:'Legacy offline browser snapshot',source:'IndexedDB',updatedAt:row.updatedAt||'',data:row.payload}]:[]);};}catch(_){db.close();finish([]);}};});}
async function discover(){const found=detectLocalStorage();try{found.push(...await readIndexedDb());}catch(_){}try{if(typeof global.__POOL_SHED_READ_LEGACY_REMOTE__==='function'){const remote=await global.__POOL_SHED_READ_LEGACY_REMOTE__();arr(remote).forEach((r,i)=>{if(r&&r.data)found.push({id:r.id||'remote:'+i,label:r.label||'Legacy Supabase snapshot',source:'Supabase',updatedAt:r.updatedAt||'',data:r.data});});}}catch(_){}const dedup=[],seen=new Set();found.forEach(item=>{let signature='';try{signature=JSON.stringify(item.data);}catch(_){}const key=item.id+'|'+signature;if(!seen.has(key)){seen.add(key);dedup.push(item);}});return dedup;}
global.PoolShedLegacyMigration={version:VERSION,summarise,plan,apply,deriveLegacySuppliers,detectLocalStorage,readIndexedDb,discover};
